<script lang="ts">
  import { onMount } from 'svelte';
  import { Capacitor } from '@capacitor/core';
  import { App } from '@capacitor/app';
  import { Users, ChevronDown, Settings, Smartphone, Router, Globe, ArrowLeft, Search, ChevronRight, Battery, Plus, RotateCw, UserPlus, AudioLines, Map, MapPin, Bell, Palette, Info, Volume2, Headphones, Mic, MicOff, Network, MessageCircle, LocateFixed, Minus, X, CircleCheck, Circle, Lock, Send } from '@lucide/svelte';
  const I = { Users, ChevronDown, Settings, Smartphone, Router, Globe, ArrowLeft, Search, ChevronRight, Battery, Plus, RotateCw, UserPlus, AudioLines, Map, MapPin, Bell, Palette, Info, Volume2, Headphones, Mic, MicOff, Network, MessageCircle, LocateFixed, Minus, X, CircleCheck, Circle, Lock, Send };
  import TopoMap from '$lib/TopoMap.svelte';
  import ConnectedApp from '$lib/ConnectedApp.svelte';
  let demo = false;
  import { members, nodes, categories, initialMessages, type Message, type InputMode } from '$lib/state';
  import '../styles.css';
  let tab = 'Map', settings = '', search = '', source = 'Alex', mode: InputMode = 'Always on';
  let muted = false, deafened = false, joined = true, talking = false, sharing = false, location = true;
  let nodeName = 'Rowan’s node', editName = nodeName, selectedNode = 'AUMA-01', groupName = 'High Country crew';
  let messages: Message[] = [...initialMessages], draft = '', toast = '', selectedMember = '', zoom = 1;
  let dataLimit = '500 MB';
  let mapReset = 0;
  let route = 'Speaker', sensitivity = 50, notifications = true, theme = 'Light', units = 'Metric';
  let mapReady = true, modal = '', newGroupName = '', storageError = false;
  let scroller: HTMLElement;
  let toastTimer: ReturnType<typeof setTimeout>;
  const icons: Record<string, any> = I;
  const tabs = [['Map', I.Map], ['Messages', I.MessageCircle], ['Voice', I.Mic], ['Group', I.Users], ['Network', I.Network]] as const;
  $: voiceState = muted ? 'Mic muted' : talking ? 'Transmitting' : mode === 'Always on' ? 'Mic on · Voice activated' : 'Mic off · Hold to talk';
  $: connectedMembers = members.filter(member => member.online).length;
  $: activeNode = nodes.find(n => n.id === selectedNode) ?? nodes[0];
  function notify(text: string) { toast = text; clearTimeout(toastTimer); toastTimer = setTimeout(() => toast = '', 3500); }
  function persist() {
    try { localStorage.setItem('aumanet-demo-v1', JSON.stringify({source, mode, sharing, location, nodeName, messages, route, sensitivity, notifications, theme, units, mapReady, groupName, dataLimit})); }
    catch { storageError = true; notify('Storage unavailable. Changes last for this session.'); }
  }
  function open(page: string) { talking = false; settings = page; search = ''; if (page === 'Node settings') editName = selectedNode === 'AUMA-01' ? nodeName : activeNode.name; scroller?.scrollTo(0,0); }
  function navigate(page: string) { talking = false; tab = page; settings = ''; selectedMember = ''; scroller?.scrollTo(0,0); }
  function chooseSource(name: string) { source = name; persist(); notify(name ? `Demo internet connected through ${name}` : 'Shared internet disconnected'); }
  function send() { if (!draft.trim()) return; messages = [...messages, {id:Date.now(), author:'Rowan', text:draft.trim(), time:new Date().toLocaleTimeString('en-AU',{hour:'2-digit',minute:'2-digit',hour12:false}), status:'Sent · Demo'}]; draft=''; persist(); setTimeout(() => scroller?.scrollTo({top:scroller.scrollHeight,behavior:'smooth'}),0); }
  function setMode(value: InputMode) { mode = value; talking = false; persist(); }
  function showDialog(node: HTMLDialogElement) { node.showModal(); return { destroy() { node.close(); } }; }
  function stopTalking() { talking = false; }
  function startTalking(event: PointerEvent) { if (!muted && joined) { talking=true; (event.currentTarget as HTMLElement).setPointerCapture(event.pointerId); } }
  onMount(() => {
    demo = new URLSearchParams(window.location.search).get('demo') === '1';
    if (!demo) return;
    try { const raw = localStorage.getItem('aumanet-demo-v1'); if(raw) { const p=JSON.parse(raw); source=['Alex','Sam',''].includes(p.source)?p.source:'Alex'; mode=p.mode==='Push to talk'?'Push to talk':'Always on'; sharing=!!p.sharing; location=p.location!==false; nodeName=typeof p.nodeName==='string'?p.nodeName:nodeName; editName=nodeName; if(Array.isArray(p.messages)) messages=p.messages.filter((m:Message)=>typeof m.text==='string' && typeof m.author==='string'); route=['Speaker','Earpiece'].includes(p.route)?p.route:'Speaker'; sensitivity=Number.isFinite(p.sensitivity)?p.sensitivity:50; notifications=p.notifications!==false; theme=p.theme==='Dark'?'Dark':'Light'; units=p.units==='Imperial'?'Imperial':'Metric'; mapReady=p.mapReady!==false; dataLimit=['500 MB','1 GB','2 GB'].includes(p.dataLimit)?p.dataLimit:'500 MB'; groupName=typeof p.groupName==='string'?p.groupName:groupName; } } catch { storageError=true; }
    const backListener = Capacitor.isNativePlatform() ? App.addListener('backButton', () => { if(modal) modal=''; else if(settings) open(settings==='Settings'?'':settings==='Node settings'?'Nodes':'Settings'); else if(tab!=='Map') navigate('Map'); else App.exitApp(); }) : null;
    const release = () => stopTalking(); window.addEventListener('blur',release); document.addEventListener('visibilitychange',release);
    return () => { clearTimeout(toastTimer); backListener?.then(handle=>handle.remove()); window.removeEventListener('blur',release); document.removeEventListener('visibilitychange',release); };
  });
</script>

<svelte:head><title>{demo?'AuMaNET · Off-grid together':'AuMaNET · Companion'}</title><meta name="description" content={demo?'AuMaNET UI preview with local sample data.':'Connect to an AuMaNET node with Bluetooth. Real messages, device status, location and microphone access.'} /></svelte:head>
{#if !demo}<ConnectedApp/>{:else}
<div class:dark={theme==='Dark'} class="app-shell">
  <header>
    <div class="brandline"><a href="/" onclick={(e)=>{e.preventDefault();navigate('Map');}} aria-label="AuMaNET home"><img class="brand-logo" src={theme==='Dark'?'/brand/aumanet-mark-light.svg':'/brand/aumanet-mark.svg'} alt="" width="44" height="22"/><strong>AuMaNET</strong></a><span class="demo">DEMO · SAMPLE DATA</span></div>
    {#if !settings}
      <div class="groupbar"><button class="group" onclick={()=>{newGroupName=groupName;modal='group';}}><I.Users size={20}/><span>{groupName}</span><I.ChevronDown size={18}/></button><button class="square" aria-label="Open settings" onclick={()=>open('Settings')}><I.Settings size={22}/></button></div>
      <div class="statusbar"><span><I.Smartphone size={14}/>Phone linked</span><span><I.Router size={14}/>3 nodes online</span><span class:warning={!source}><I.Globe size={14}/>{source ? `Via ${source}` : 'No internet'}</span></div>
    {:else}
      <div class="pagebar"><button class="square" aria-label="Back" onclick={()=>open(settings==='Settings'?'':settings==='Node settings'?'Nodes':'Settings')}><I.ArrowLeft size={22}/></button><h1>{settings}</h1></div>
    {/if}
  </header>

  <main bind:this={scroller} class:voice-main={!settings && tab==='Voice'} class:map-main={!settings && tab==='Map'}>
    {#if settings === 'Settings'}
      <label class="search"><I.Search size={20}/><input placeholder="Search settings" aria-label="Search settings" bind:value={search}/></label>
      <div class="profile card"><span class="avatar">R</span><div><h2>Rowan · This phone</h2><p>{groupName}</p></div></div>
      <div class="settings-list">{#each categories.filter(c=>`${c[0]} ${c[1]}`.toLowerCase().includes(search.toLowerCase())) as category}
        {@const Icon = icons[category[2]]}<button class="setting-row" onclick={()=>open(category[0])}><span class="icon-tile"><Icon size={23}/></span><span><strong>{category[0]}</strong><small>{category[1]}</small></span><I.ChevronRight size={18}/></button>
      {/each}</div>
      {#if !categories.some(c=>`${c[0]} ${c[1]}`.toLowerCase().includes(search.toLowerCase()))}<div class="empty">No settings match “{search}”.</div>{/if}
    {:else if settings === 'Nodes'}
      <p class="eyebrow">PAIRED RADIO DEVICES</p><h2>Your nodes</h2><p>Inspect a node or manage its configuration.</p>
      {#each nodes as node}<button class="node-row card" onclick={()=>{selectedNode=node.id;open('Node settings');}}><I.Router size={32}/><span><strong>{node.id==='AUMA-01'?nodeName:node.name}</strong><small>{node.id} · {node.id==='AUMA-01'?'Your node':'View only'}</small></span><span class="pill"><I.Battery size={15}/>{node.battery}%</span><I.ChevronRight size={18}/></button>{/each}
      <button class="primary full" onclick={()=>modal='pair'}><I.Plus size={18}/>Pair a node</button>
    {:else if settings === 'Node settings'}
      <div class="card device-summary"><I.Router size={48}/><div><h2>{activeNode.id}</h2><span class="pill">{selectedNode==='AUMA-01'?'Your node · Connected':'Remote node · View only'}</span><p>Battery {activeNode.battery}% · Updated just now</p></div></div>
      <section class="card"><h3>General</h3><label class="field">Node name<input maxlength="40" bind:value={editName} disabled={selectedNode!=='AUMA-01'}/></label><div class="info-row"><span>Device ID</span><strong>{selectedNode}</strong></div></section>
      <section class="card"><h3>Connection & mesh</h3><div class="info-row"><span>Phone pairing</span><strong>{selectedNode==='AUMA-01'?'This phone · Verified':'Remote phone'}</strong></div><div class="info-row"><span>Group</span><strong>{groupName}</strong></div><div class="info-row"><span>Radio profile</span><strong>Device-managed</strong></div><p class="hint">Available controls depend on connected hardware.</p><div class="info-row"><span>Relay status</span><span class="pill">Active</span></div><p class="hint">Relays without a connected phone.</p></section>
      <section class="card"><h3>Maintenance</h3><button class="text-row" onclick={()=>modal='firmware'}>Firmware & updates<I.ChevronRight size={18}/></button><button class="text-row" onclick={()=>open('Diagnostics & about')}>Node diagnostics<I.ChevronRight size={18}/></button></section>
      {#if selectedNode==='AUMA-01'}<button class="outline full" onclick={()=>modal='restart'}><I.RotateCw size={18}/>Restart node</button><button class="danger full" onclick={()=>modal='unpair'}>Unpair this phone</button><p class="hint">Changes apply to {selectedNode} only.</p><button class="primary full" disabled={!editName.trim() || editName.trim()===nodeName} onclick={()=>{nodeName=editName.trim();editName=nodeName;persist();notify('Demo node settings saved');}}>Save changes</button>{/if}
    {:else if settings === 'Group & members'}
      <section class="card"><h2>{groupName}</h2><p>Private group · 4 members</p><button class="outline full" onclick={()=>modal='invite'}><I.UserPlus size={18}/>Invite a member</button></section>{#each members as member}<div class="member-row card"><span class="avatar">{member.initials}</span><div><strong>{member.name}</strong><small>{member.name==='Rowan'?'Owner · This phone':member.online?'Member · Connected':'Member · Last seen 2 min ago'}</small></div></div>{/each}
    {:else if settings === 'Voice & audio'}
      <section class="card"><h3>Input mode</h3><div class="segments">{#each ['Push to talk','Always on'] as option}<button class:active={mode===option} aria-pressed={mode===option} onclick={()=>setMode(option as InputMode)}>{option}</button>{/each}</div><p class="hint">Always on transmits only when your voice is detected.</p></section><section class="card"><h3>Voice detection</h3><label class="field">Sensitivity <input type="range" min="0" max="100" bind:value={sensitivity} onchange={persist}/></label><p class="hint">Demo preference: {sensitivity}%. Audio detection is simulated.</p></section><section class="card"><label class="field">Audio route<select bind:value={route} onchange={persist}><option>Speaker</option><option>Earpiece</option></select></label></section>
    {:else if settings === 'Internet sharing'}
      <h2>Use shared internet</h2><p>Choose the phone providing your connection.</p>{#each ['Alex','Sam'] as donor}<button class="source-row card" class:selected={source===donor} onclick={()=>chooseSource(donor)}><I.Smartphone size={24}/><span><strong>{donor}’s phone</strong><small>Sharing · {donor==='Alex'?'1 hop':'2 hops'}</small></span>{#if source===donor}<I.CircleCheck size={22}/>{:else}<I.Circle size={22}/>{/if}</button>{/each}<button class="outline full" disabled={!source} onclick={()=>chooseSource('')}>Disconnect shared internet</button><section class="card"><h3>Provide internet</h3><label class="switch-row"><span>Share my internet<small>Separate from using another phone’s connection</small></span><input type="checkbox" role="switch" bind:checked={sharing} onchange={persist}/></label><label class="field">Demo daily data limit<select bind:value={dataLimit} onchange={persist}><option>500 MB</option><option>1 GB</option><option>2 GB</option></select></label></section>
    {:else if settings === 'Maps & storage'}
      <section class="card"><div class="section-heading"><I.Map size={27}/><h2>Victorian High Country</h2></div><p>Illustrative region · Local demo terrain</p><span class="pill">{mapReady?'Ready offline':'Not installed'}</span><p class="hint">Bundled vector illustration. No downloaded geographic data or navigation.</p><button class="outline full" onclick={()=>{mapReady=!mapReady;persist();notify(mapReady?'Demo region restored':'Demo region removed');}}>{mapReady?'Remove demo region':'Restore demo region'}</button></section><section class="card"><h3>Message history</h3><p>{messages.length} messages stored on this phone</p><button class="danger full" onclick={()=>modal='clear'}>Clear message history</button></section>
    {:else if settings === 'Location & privacy'}
      <section class="card"><label class="switch-row"><span>Share my location<small>With members of {groupName}</small></span><input type="checkbox" role="switch" bind:checked={location} onchange={persist}/></label><p class="hint">Only sample positions are used. This demo does not request your real location.</p></section><section class="card"><h3>Track history</h3><p>Off · No location history is recorded.</p></section>
    {:else if settings === 'Notifications'}
      <section class="card"><label class="switch-row"><span>Group alerts<small>Messages, voice and connection events</small></span><input type="checkbox" role="switch" bind:checked={notifications} onchange={persist}/></label><p class="hint">Demo preference only. No system notifications are sent.</p></section>
    {:else if settings === 'Appearance'}
      <section class="card"><label class="field">Theme<select bind:value={theme} onchange={persist}><option>Light</option><option>Dark</option></select></label><label class="field">Units<select bind:value={units} onchange={persist}><option>Metric</option><option>Imperial</option></select></label><p class="hint">Distances display in {units==='Metric'?'metres':'feet'}.</p></section>
    {:else if settings === 'Diagnostics & about'}
      <section class="card"><h2>AuMaNET</h2><p>UI prototype · 0.1.0</p><span class="pill">Simulator only</span><p>No radio, microphone, location or internet routing is active.</p><div class="info-row"><span>Phone → node</span><strong>Demo connected</strong></div><div class="info-row"><span>Mesh nodes</span><strong>3 simulated</strong></div><div class="info-row"><span>Internet source</span><strong>{source || 'None'}</strong></div><div class="info-row"><span>Local storage</span><strong>{storageError?'Unavailable':'Available'}</strong></div></section>
    {:else if tab === 'Map'}
      <div class="map-container">{#if mapReady}<TopoMap reset={mapReset} {zoom} {location} selected={selectedMember} onselect={(name)=>{selectedMember=name;setTimeout(()=>scroller?.scrollTo({top:scroller.scrollHeight,behavior:'smooth'}),0);}}/>{:else}<div class="empty map-missing"><I.Map size={42}/><h2>No offline region</h2><p>Member coordinates remain available.</p><button class="primary" onclick={()=>open('Maps & storage')}>Manage maps</button></div>{/if}<div class="map-controls"><button class="square" aria-label="Zoom in" disabled={zoom>=1.8} onclick={()=>zoom=Math.min(1.8,zoom+.2)}><I.Plus size={21}/></button><button class="square" aria-label="Zoom out" disabled={zoom<=.8} onclick={()=>zoom=Math.max(.8,zoom-.2)}><I.Minus size={21}/></button><button class="square" aria-label="Recenter map" onclick={()=>{zoom=1;mapReset++;selectedMember='';notify('Map recentered');}}><I.LocateFixed size={21}/></button></div></div>
      {#if selectedMember}<div class="card map-detail"><span class="avatar">{selectedMember[0]}</span><div><strong>{selectedMember}</strong><small>Sample fix · {selectedMember==='Alex'?'2 min ago':'Just now'} · ±{units==='Metric'?'12 m':'39 ft'}</small><small>−37.1670, 146.4360 · Illustrative</small></div><button class="square" aria-label="Close member details" onclick={()=>selectedMember=''}><I.X size={18}/></button></div>{/if}
      <div class="map-summary"><button class="map-members" onclick={()=>modal='roster'} aria-label="View all 4 group members"><I.Users size={22}/><span><strong>4 members<I.ChevronRight size={16}/></strong><small>{connectedMembers} connected · 1 disconnected</small></span></button><span><I.Battery size={20}/>Node 82%</span></div>
    {:else if tab === 'Messages'}
      <div class="title-row"><div><p class="eyebrow">{groupName.toUpperCase()}</p><h1>Messages</h1></div><a class="pill" href="/bench">Live hardware bench</a></div><div class="banner"><I.Info size={17}/>Group messages work without internet</div>
      <div class="conversation">{#each messages as message}<article class:own={message.author==='Rowan'} class="message"><div class="message-meta">{message.author}<time>{message.time}</time></div><div class="bubble">{message.text}</div>{#if message.status}<small>{message.status}</small>{/if}</article>{/each}{#if !messages.length}<div class="empty">No messages yet. Say hello to your group.</div>{/if}</div>
    {:else if tab === 'Voice'}
      <div class="title-row"><h1>Voice</h1><I.AudioLines size={26}/></div><section class="channel"><I.Users size={28}/><div><h2>Convoy voice</h2><small>Live group audio over mesh</small></div><span class="pill">{joined?'Joined':'Not joined'}</span></section>
      <section class="card voice-controls"><h3>Input mode</h3><div class="segments">{#each ['Push to talk','Always on'] as option}<button class:active={mode===option} aria-pressed={mode===option} onclick={()=>setMode(option as InputMode)}>{option}</button>{/each}</div>{#if mode==='Always on'}<div class="detection"><I.AudioLines size={25}/><div><strong>{joined?voiceState:'Mic off · Join to talk'}</strong><small>Your speech is sent to Convoy voice automatically. Audio is simulated.</small></div></div>{:else}<button class="ptt full" disabled={muted||!joined} onpointerdown={startTalking} onpointerup={stopTalking} onpointercancel={stopTalking} onlostpointercapture={stopTalking} onkeydown={(e)=>{if((e.code==='Space'||e.code==='Enter')&&!e.repeat&&!muted&&joined){e.preventDefault();talking=true;}}} onkeyup={stopTalking} onblur={stopTalking}><I.Mic size={24}/>{talking?'Transmitting · Demo':'Hold to talk'}</button>{/if}<p class="hint">{!joined?'Join the channel to talk.':muted?'Your microphone is muted. Unmute before talking.':mode==='Push to talk'?'Your mic is off until you hold the button. Release to stop.':'Use Mute to stop sending your voice.'}</p></section>
      {#if joined}<div class="two-col"><button class:pressed={muted} class="outline" aria-pressed={muted} onclick={()=>{muted=!muted;talking=false;}}>{#if muted}<I.MicOff size={21}/>{:else}<I.Mic size={21}/>{/if}{muted?'Unmute':'Mute'}</button><button class:pressed={deafened} class="outline" aria-pressed={deafened} onclick={()=>deafened=!deafened}><I.Headphones size={21}/>{deafened?'Undeafen':'Deafen'}</button></div>{/if}
      <label class="route card"><span><I.Volume2 size={20}/>Audio route</span><select bind:value={route} onchange={persist}><option>Speaker</option><option>Earpiece</option></select></label>
      <section class="card participants">{#each members.slice(0,3) as member}<div class="member-row"><span class="avatar" class:speaking={joined && member.name==='Alex'}>{member.initials}</span><div><strong>{member.name}{member.name==='Rowan'?' · You':''}</strong><small>{!joined?'Not in channel':member.name==='Rowan'?voiceState:member.name==='Alex'?'Speaking · Simulated':'Listening'}</small></div>{#if member.name==='Alex' && joined}<I.AudioLines class="wave" size={28}/>{:else}<I.Mic size={20}/>{/if}</div>{/each}<p class="hint">Jess is not in voice · Audio is simulated</p></section>
<button class="text-row card" onclick={()=>open('Voice & audio')}>Voice detection settings<I.ChevronRight size={18}/></button><button class="full" class:danger={joined} class:primary={!joined} onclick={()=>{joined=!joined;talking=false;}}>{joined?'Leave channel':'Join channel'}</button>
    {:else if tab === 'Group'}
      <div class="title-row"><div><p class="eyebrow">{groupName}</p><h1>Group</h1></div><I.Users size={28}/></div>
      <section class="card"><div class="title-row"><div><h2>{members.length} members</h2><p>{connectedMembers} connected · {members.length-connectedMembers} disconnected</p></div><button class="outline" onclick={()=>open('Group & members')}>Manage group</button></div><p class="hint">Sample members · Activity is simulated</p></section>
      {#each members as member}<button class="member-row card full text-row" onclick={()=>{selectedMember=member.name;modal='member';}}><span class="avatar">{member.initials}</span><span><strong>{member.name}{member.name==='Rowan'?' · You':''}</strong><small>{member.name==='Rowan'?'Group owner':'Member'} · {member.node||'Phone disconnected'}</small><small>{member.online?'Connected':'Last seen 2 min ago'}</small></span><I.ChevronRight size={18}/></button>{/each}
    {:else if tab === 'Network'}
      <div class="title-row"><div><h1>Network</h1><p>Nodes & group members</p></div><I.Network size={28}/></div>
      <section class="card topology"><h3>Node connections</h3><p class="hint">Solid: node mesh · Dashed: phone link</p><div class="topology-grid">{#each nodes as node,i}<div class="topo-column"><button class="radio" onclick={()=>{selectedNode=node.id;open('Node settings');}} aria-label="Inspect {node.id}"><I.Router size={34}/><strong>{node.id}</strong></button><div class="phone-link"></div><I.Smartphone size={26}/><strong>{members[i].name}</strong><span class="tiny-pill">{i===0?'No uplink':'Internet · Sharing'}</span></div>{/each}</div><p class="hint">Nodes relay without a connected phone.</p></section>
      <section class="card sources"><h3><I.Globe size={21}/>Use shared internet</h3><p>Choose a device to connect through.</p>{#each ['Alex','Sam'] as donor}<button class="source-row" class:selected={source===donor} aria-pressed={source===donor} onclick={()=>chooseSource(donor)}>{#if source===donor}<I.CircleCheck size={23}/>{:else}<I.Circle size={23}/>{/if}<div><strong>{donor}’s phone</strong><small>Sharing · AUMA-0{donor==='Alex'?'2 · 1 hop':'3 · 2 hops'}</small></div><span class="pill">{source===donor?'Connected':'Use'}</span></button>{/each}<div class="source-row unavailable"><I.Lock size={22}/><div><strong>Jess’s phone</strong><small>Last seen 2 min ago · Unavailable</small></div></div>{#if source}<p class="current-route">You → AUMA-01 → {source==='Alex'?'AUMA-02':'AUMA-02 → AUMA-03'} → {source} → Internet</p><button class="text-button" onclick={()=>chooseSource('')}>Disconnect shared internet</button>{:else}<p class="hint">No source selected. Local group features remain available.</p>{/if}</section>
      <section class="card"><h3>Group members · 4</h3>{#each members as member}<button class="member-row text-row" onclick={()=>{selectedMember=member.name;modal='member';}}><span class="avatar small">{member.initials}</span><span><strong>{member.name}{member.name==='Rowan'?' · You':''}</strong><small>{member.node || 'Phone disconnected'}</small></span><span class:warning={!member.online} class="pill">{member.online?'Connected':'Seen 2m ago'}</span></button>{/each}</section><section class="card"><label class="switch-row"><span>Share my internet<small>Let this phone provide internet to the group</small></span><input type="checkbox" role="switch" bind:checked={sharing} onchange={persist}/></label></section>
    {/if}
  </main>

  {#if !settings && tab==='Messages'}<form class="composer" onsubmit={(e)=>{e.preventDefault();send();}}><input aria-label="Message convoy" placeholder="Message convoy" maxlength="1000" bind:value={draft}/><button class="primary square" type="submit" aria-label="Send message" disabled={!draft.trim()}><I.Send size={20}/></button></form>{/if}
  {#if joined && (settings || tab!=='Voice')}<div class="voice-strip"><button class="strip-title" onclick={()=>navigate('Voice')}><I.AudioLines size={22}/><span><strong>Convoy voice</strong><small>{muted?'Mic muted':talking?'Transmitting · Demo':mode==='Always on'?'Mic on · Voice activated':'Mic off · Push to talk'}</small></span></button><button class="strip-mic" aria-label={muted?'Unmute microphone':'Mute microphone'} aria-pressed={muted} onclick={()=>{muted=!muted;talking=false;}}>{#if muted}<I.MicOff size={21}/>{:else}<I.Mic size={21}/>{/if}</button>{#if mode==='Push to talk'}<button class="strip-ptt" disabled={muted} onpointerdown={startTalking} onpointerup={stopTalking} onpointercancel={stopTalking} onlostpointercapture={stopTalking} onkeydown={(e)=>{if((e.code==='Space'||e.code==='Enter')&&!muted){e.preventDefault();talking=true;}}} onkeyup={stopTalking} onblur={stopTalking}>{talking?'Talking':'Hold to talk'}</button>{:else}<span class="strip-state">{muted?'Muted':'Auto voice'}</span>{/if}</div>{/if}
  {#if !settings}<nav aria-label="Primary navigation">{#each tabs as [name,Icon]}<button class:active={tab===name} aria-current={tab===name?'page':undefined} onclick={()=>navigate(name)}><span><Icon size={23}/></span>{name}</button>{/each}</nav>{/if}
  {#if toast}<div role="status" class="toast">{toast}</div>{/if}
  {#if modal}<dialog use:showDialog class="dialog" oncancel={()=>modal=''} aria-label={modal==='group'?'Group details':modal==='member'?'Member details':modal==='roster'?'Group members':modal} tabindex="-1"><div class="dialog-head"><h2>{modal==='group'?'Your group':modal==='roster'?'Group members':modal==='member'?selectedMember:modal==='pair'?'Pair a node':modal==='restart'?'Restart node?':modal==='unpair'?'Unpair this phone?':modal==='clear'?'Clear messages?':modal==='invite'?'Group invitation':'Firmware & updates'}</h2><button class="square" aria-label="Close dialog" onclick={()=>modal=''}><I.X size={22}/></button></div>
    {#if modal==='group'}<label class="field">Group name<input bind:value={newGroupName} maxlength="40"/></label><p class="hint">Demo group details are stored on this phone.</p><button class="primary full" disabled={!newGroupName.trim()} onclick={()=>{groupName=newGroupName.trim();persist();modal='';}}>Save group name</button>
    {:else if modal==='roster'}
      <p>{groupName} · {connectedMembers} connected · 1 disconnected</p>
      <div class="roster-list">{#each members as member}
        {#if member.online}<button class="member-row text-row" onclick={()=>{modal='';navigate('Map');selectedMember=member.name;setTimeout(()=>scroller?.scrollTo({top:scroller.scrollHeight,behavior:'smooth'}),0);}}>
          <span class="avatar small">{member.initials}</span><span><strong>{member.name}{member.name==='Rowan'?' · You':''}</strong><small>{member.name==='Rowan'&&!location?'Location sharing paused':member.name==='Alex'?'Sample fix · 2 min ago':'Sample fix · Just now'}</small></span><I.MapPin size={20}/>
        </button>{:else}<div class="member-row"><span class="avatar small">{member.initials}</span><div><strong>{member.name}</strong><small>Disconnected · Last seen 2 min ago</small><small>No current position available</small></div></div>{/if}
      {/each}</div><p class="hint">Tap a connected member to see their sample position.</p>
    {:else if modal==='member'}<p>{members.find(m=>m.name===selectedMember)?.online?'Connected to '+members.find(m=>m.name===selectedMember)?.node:'Phone disconnected · Last seen 2 min ago'}</p><p class="hint">Membership and positions are simulated.</p>
    {:else if modal==='pair'}<I.Router size={48}/><p>Demo node AUMA-04 discovered</p><p class="hint">This prototype has three fixed nodes. Real device discovery and authenticated pairing are not connected.</p><button class="primary full" onclick={()=>{modal='';notify('Demo only — no device was paired');}}>Finish preview</button>
    {:else if modal==='firmware'}<p>Demo firmware · No hardware connected</p><p class="hint">Firmware installation will be available after device integration.</p>
    {:else if modal==='invite'}<I.Users size={40}/><p>Invitation preview · {groupName}</p><p class="hint">Real invitations require authenticated local group membership. No usable invitation or key is generated in this demo.</p>
    {:else}<p>{modal==='restart'?'A real restart temporarily interrupts this node’s mesh links. This demo will only show a confirmation.':modal==='unpair'?'This would remove this phone’s pairing. The node would continue relaying. Demo connections stay intact.':'This removes the demo conversation from local storage.'}</p><button class="danger full" onclick={()=>{if(modal==='clear'){messages=[];persist();}notify(modal==='clear'?'Message history cleared':'Demo action completed — hardware unchanged');modal='';}}>Confirm {modal==='clear'?'clear':modal==='restart'?'demo restart':'demo unpair'}</button>{/if}
  </dialog>{/if}
</div>
{/if}

